// ---- Other acts that have a niat (0.1.6). Lafaz as commonly taught in Malaysia (Shafi'i). VERIFY by ustaz. ----
var SUNAT_TOP=[["solat","Solat","Prayer"],["puasa","Puasa","Fasting"],["sedekah","Sedekah & Zakat","Charity & Zakat"],["bersuci","Bersuci","Purification"],["haji","Haji & Umrah","Hajj & Umrah"],["lain","Lain-lain","Others"]];
SUNAT_LIST.forEach(function(x){ x.top="solat"; });
function NV(ar,ms,en,lms,len){ return {ar:ar,ms:ms,en:en,label:lms?{ms:lms,en:len}:null}; }
function T2(ms,en){ return {ms:ms,en:en}; }
var FAST_NOTE=T2("Puasa fardu (Ramadan, qada', nazar) wajib berniat pada malam hari sebelum fajar. Puasa sunat sah berniat sebelum gelincir matahari (zawal) jika belum makan, minum atau membatalkan puasa sejak fajar.","Obligatory fasts (Ramadan, make-up, vowed) require the intention at night before dawn. A sunnah fast is valid with an intention made before midday (zawal) if nothing that breaks the fast has been done since dawn.");
SUNAT_LIST=SUNAT_LIST.concat([
{id:"p_ramadan",top:"puasa",n:[],name:T2("Puasa Ramadan (fardu)","Ramadan fast (obligatory)"),
 niat:[NV("نَوَيْتُ صَوْمَ غَدٍ عَنْ أَدَاءِ فَرْضِ شَهْرِ رَمَضَانَ هَٰذِهِ السَّنَةِ لِلَّهِ تَعَالَى","Sahaja aku berpuasa esok hari bagi menunaikan fardu bulan Ramadan tahun ini kerana Allah Ta'ala.","I intend to fast tomorrow to fulfil the obligation of Ramadan this year, for the sake of Allah the Most High.","Setiap malam",
 "Every night"),NV("نَوَيْتُ صَوْمَ جَمِيعِ شَهْرِ رَمَضَانَ هَٰذِهِ السَّنَةِ لِلَّهِ تَعَالَى","Sahaja aku berpuasa sepanjang bulan Ramadan tahun ini kerana Allah Ta'ala.","I intend to fast the whole month of Ramadan this year, for the sake of Allah the Most High.","Malam pertama, sebagai langkah berjaga-jaga (pendapat mazhab Maliki) jika terlupa niat pada malam lain","First night, as a precaution (Maliki view) in case a night's intention is forgotten")],
 what:T2("Puasa wajib sebulan Ramadan, salah satu rukun Islam.","The obligatory month-long fast of Ramadan, one of the pillars of Islam."),
 why:T2("Sesiapa berpuasa Ramadan dengan iman dan mengharap pahala, diampunkan dosanya yang lalu.","Whoever fasts Ramadan with faith and hoping for reward, his past sins are forgiven."),
 how:T2("Menahan diri daripada makan, minum dan perkara yang membatalkan puasa dari terbit fajar hingga terbenam matahari. Disunatkan bersahur dan menyegerakan berbuka.","Refrain from eating, drinking and everything that breaks the fast from dawn until sunset. Suhur and hastening iftar are sunnah."),
 when:T2("Sepanjang bulan Ramadan. Niat setiap malam sebelum fajar.","Throughout Ramadan. Intention each night before dawn."),
 src:"Al-Quran 2:183-185; Sahih al-Bukhari 38; Sahih al-Bukhari 1923", note:FAST_NOTE},
{id:"p_qada",top:"puasa",n:[],name:T2("Qada' puasa Ramadan","Making up Ramadan fasts"),
 niat:[NV("نَوَيْتُ صَوْمَ غَدٍ عَنْ قَضَاءِ فَرْضِ شَهْرِ رَمَضَانَ لِلَّهِ تَعَالَى","Sahaja aku berpuasa esok hari bagi menggantikan fardu bulan Ramadan kerana Allah Ta'ala.","I intend to fast tomorrow to make up an obligatory fast of Ramadan, for the sake of Allah the Most High.")],
 what:T2("Menggantikan hari puasa Ramadan yang ditinggalkan kerana uzur seperti sakit, musafir, haid atau nifas.","Making up Ramadan days missed for a valid reason such as illness, travel, menstruation or post-natal bleeding."),
 why:T2("Ia wajib: \"maka (wajiblah ia berpuasa) sebanyak hari yang ditinggalkan itu pada hari-hari yang lain.\"","It is obligatory: \"then an equal number of other days.\""),
 how:T2("Sama seperti puasa Ramadan. Niat pada malam hari.","Same as a Ramadan fast. Intention at night."),
 when:T2("Sebelum Ramadan berikutnya. Jika dilewatkan tanpa uzur, wajib fidyah selain qada' (mazhab Syafi'i).","Before the next Ramadan. If delayed without excuse, fidyah is due in addition (Shafi'i school)."),
 src:"Al-Quran 2:184; Sahih al-Bukhari 1950", note:FAST_NOTE},
{id:"p_isnin",top:"puasa",n:[],name:T2("Puasa Isnin & Khamis","Monday & Thursday fasts"),
 niat:[NV("نَوَيْتُ صَوْمَ يَوْمِ الْاِثْنَيْنِ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat hari Isnin kerana Allah Ta'ala.","I intend to fast Monday as a sunnah, for the sake of Allah the Most High.","Isnin","Monday"),
       NV("نَوَيْتُ صَوْمَ يَوْمِ الْخَمِيسِ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat hari Khamis kerana Allah Ta'ala.","I intend to fast Thursday as a sunnah, for the sake of Allah the Most High.","Khamis","Thursday")],
 what:T2("Puasa sunat setiap hari Isnin dan Khamis.","A sunnah fast every Monday and Thursday."),
 why:T2("Amalan dibentangkan kepada Allah pada hari Isnin dan Khamis, dan Nabi ﷺ suka amalannya dibentangkan ketika baginda berpuasa. Isnin ialah hari kelahiran baginda.","Deeds are presented to Allah on Mondays and Thursdays, and the Prophet ﷺ loved his deeds to be presented while fasting. Monday is the day he was born."),
 how:T2("Seperti puasa biasa.","Like any fast."),
 when:T2("Setiap Isnin dan Khamis.","Every Monday and Thursday."),
 src:"Jami' at-Tirmidhi 747; Sahih Muslim 1162", note:FAST_NOTE},
{id:"p_bidh",top:"puasa",n:[],name:T2("Puasa Ayyamul Bidh","The White Days fast"),
 niat:[NV("نَوَيْتُ صَوْمَ أَيَّامِ الْبِيضِ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat hari-hari putih kerana Allah Ta'ala.","I intend to fast the White Days as a sunnah, for the sake of Allah the Most High.")],
 what:T2("Puasa tiga hari setiap bulan pada 13, 14 dan 15 Hijrah, ketika bulan purnama.","Fasting three days each month on the 13th, 14th and 15th of the Hijri month, when the moon is full."),
 why:T2("Puasa tiga hari setiap bulan seperti berpuasa sepanjang tahun.","Fasting three days every month is like fasting the whole year."),
 how:T2("Seperti puasa biasa. Tidak boleh pada 13 Zulhijjah (hari Tasyrik).","Like any fast. Not on 13 Dhul-Hijjah (a day of Tashriq)."),
 when:T2("13, 14, 15 setiap bulan Hijrah (lihat Kalendar).","13th, 14th, 15th of each Hijri month (see Calendar)."),
 src:"Sunan an-Nasa'i 2420; Sahih al-Bukhari 1979", note:FAST_NOTE},
{id:"p_syawal",top:"puasa",n:[],name:T2("Puasa enam Syawal","Six days of Shawwal"),
 niat:[NV("نَوَيْتُ صَوْمَ سِتَّةٍ مِنْ شَوَّالٍ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat enam hari bulan Syawal kerana Allah Ta'ala.","I intend to fast (one of) the six days of Shawwal as a sunnah, for the sake of Allah the Most High.")],
 what:T2("Puasa enam hari dalam bulan Syawal selepas Hari Raya.","Fasting six days in Shawwal after Eid."),
 why:T2("Sesiapa berpuasa Ramadan kemudian diikuti enam hari Syawal, seperti berpuasa sepanjang tahun.","Whoever fasts Ramadan then follows it with six days of Shawwal, it is as if he fasted the whole year."),
 how:T2("Boleh berturut-turut atau berselang. Tidak boleh pada 1 Syawal.","Consecutive or separate. Not on 1 Shawwal."),
 when:T2("2 hingga 30 Syawal. Afdal berturut-turut selepas Hari Raya.","2nd to 30th Shawwal. Best done consecutively right after Eid."),
 src:"Sahih Muslim 1164", note:FAST_NOTE},
{id:"p_arafah",top:"puasa",n:[],name:T2("Puasa hari Arafah","Day of Arafah fast"),
 niat:[NV("نَوَيْتُ صَوْمَ يَوْمِ عَرَفَةَ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat hari Arafah kerana Allah Ta'ala.","I intend to fast the Day of Arafah as a sunnah, for the sake of Allah the Most High.")],
 what:T2("Puasa pada 9 Zulhijjah bagi yang tidak mengerjakan haji.","Fasting on 9 Dhul-Hijjah for those not performing Hajj."),
 why:T2("Menghapuskan dosa setahun yang lalu dan setahun yang akan datang.","It expiates the sins of the past year and the coming year."),
 how:T2("Seperti puasa biasa. Jemaah haji yang berada di Arafah tidak disunatkan berpuasa.","Like any fast. Pilgrims at Arafah are not encouraged to fast."),
 when:T2("9 Zulhijjah.","9 Dhul-Hijjah."),
 src:"Sahih Muslim 1162", note:FAST_NOTE},
{id:"p_asyura",top:"puasa",n:[],name:T2("Puasa Tasu'a & Asyura","Tasu'a & Ashura fasts"),
 niat:[NV("نَوَيْتُ صَوْمَ يَوْمِ تَاسُوعَاءَ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat hari Tasu'a kerana Allah Ta'ala.","I intend to fast the day of Tasu'a as a sunnah, for the sake of Allah the Most High.","9 Muharram","9 Muharram"),
       NV("نَوَيْتُ صَوْمَ يَوْمِ عَاشُورَاءَ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat hari Asyura kerana Allah Ta'ala.","I intend to fast the day of Ashura as a sunnah, for the sake of Allah the Most High.","10 Muharram","10 Muharram")],
 what:T2("Puasa pada 9 dan 10 Muharram.","Fasting on the 9th and 10th of Muharram."),
 why:T2("Puasa Asyura menghapuskan dosa setahun yang lalu. Nabi ﷺ berazam berpuasa juga pada hari kesembilan.","The Ashura fast expiates the sins of the past year. The Prophet ﷺ resolved to also fast the 9th."),
 how:T2("Seperti puasa biasa.","Like any fast."),
 when:T2("9 & 10 Muharram.","9th & 10th Muharram."),
 src:"Sahih Muslim 1162; Sahih Muslim 1134", note:FAST_NOTE},
{id:"p_daud",top:"puasa",n:[],name:T2("Puasa Nabi Daud","The fast of Dawud"),
 niat:[NV("نَوَيْتُ صَوْمَ غَدٍ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku berpuasa sunat esok hari kerana Allah Ta'ala.","I intend to fast tomorrow as a sunnah, for the sake of Allah the Most High.")],
 what:T2("Berpuasa sehari dan berbuka sehari secara berselang-seli.","Fasting one day and not fasting the next, alternately."),
 why:T2("Puasa yang paling disukai Allah ialah puasa Nabi Daud a.s.","The most beloved fast to Allah is the fast of Dawud."),
 how:T2("Selang sehari. Elakkan hari yang diharamkan berpuasa.","Every other day, avoiding days on which fasting is forbidden."),
 when:T2("Bila-bila masa kecuali dua Hari Raya dan hari Tasyrik (11–13 Zulhijjah).","Any time except the two Eids and the days of Tashriq (11–13 Dhul-Hijjah)."),
 src:"Sahih al-Bukhari 1131; Sahih Muslim 1159", note:FAST_NOTE},
{id:"s_sedekah",top:"sedekah",n:[],name:T2("Sedekah","Charity (sadaqah)"),
 niat:[NV("نَوَيْتُ الصَّدَقَةَ لِلَّهِ تَعَالَى","Sahaja aku bersedekah kerana Allah Ta'ala.","I intend to give charity for the sake of Allah the Most High.")],
 what:T2("Memberi harta, tenaga atau kebaikan kepada orang lain semata-mata kerana Allah.","Giving wealth, effort or kindness to others purely for Allah."),
 why:T2("Sedekah tidak mengurangkan harta. Senyuman kepada saudaramu juga sedekah. Sedekah jariah terus memberi pahala selepas mati.","Charity does not decrease wealth. Smiling at your brother is charity. Ongoing charity keeps rewarding after death."),
 how:T2("Berikan daripada harta yang halal, secara ikhlas, afdal secara tersembunyi, tanpa mengungkit.","Give from lawful wealth, sincerely, preferably in secret, without reminding the recipient."),
 when:T2("Bila-bila masa. Lebih afdal pada bulan Ramadan dan hari Jumaat.","Any time; especially virtuous in Ramadan and on Fridays."),
 src:"Sahih Muslim 2588; Jami' at-Tirmidhi 1956; Sahih Muslim 1631; Sahih al-Bukhari 1902"},
{id:"s_fitrah",top:"sedekah",n:[],name:T2("Zakat fitrah","Zakat al-Fitr"),
 niat:[NV("نَوَيْتُ أَنْ أُخْرِجَ زَكَاةَ الْفِطْرِ عَنْ نَفْسِي فَرْضًا لِلَّهِ تَعَالَى","Sahaja aku mengeluarkan zakat fitrah untuk diriku sendiri, fardu kerana Allah Ta'ala.","I intend to give zakat al-fitr for myself, as an obligation, for the sake of Allah the Most High.","Untuk diri sendiri","For oneself"),
       NV("نَوَيْتُ أَنْ أُخْرِجَ زَكَاةَ الْفِطْرِ عَنْ نَفْسِي وَعَنْ جَمِيعِ مَا يَلْزَمُنِي نَفَقَاتُهُمْ شَرْعًا فَرْضًا لِلَّهِ تَعَالَى","Sahaja aku mengeluarkan zakat fitrah untuk diriku dan semua orang di bawah tanggunganku, fardu kerana Allah Ta'ala.","I intend to give zakat al-fitr for myself and everyone I am obliged to support, as an obligation, for the sake of Allah the Most High.","Untuk diri & tanggungan","For oneself and dependants")],
 what:T2("Zakat wajib bagi setiap Muslim yang hidup pada akhir Ramadan dan mempunyai lebihan keperluan pada malam Hari Raya.","An obligatory zakat for every Muslim alive at the end of Ramadan who has more than his needs on the eve of Eid."),
 why:T2("Penyuci bagi orang berpuasa daripada perkara sia-sia dan kata-kata keji, serta makanan bagi orang miskin.","A purification for the fasting person from idle and indecent speech, and food for the poor."),
 how:T2("Satu gantang Baghdad makanan asasi (beras) atau nilainya mengikut kadar yang ditetapkan oleh Majlis Agama Islam negeri, bayar kepada amil yang dilantik.","One gantang Baghdad of staple food (rice) or its value at the rate set by the state Islamic council, paid to an appointed amil."),
 when:T2("Sepanjang Ramadan. Wajib sebelum solat Hari Raya Aidilfitri.","Throughout Ramadan; must be paid before the Eid al-Fitr prayer."),
 src:"Sunan Abi Dawud 1609; Sahih al-Bukhari 1503"},
{id:"s_wakaf",top:"sedekah",n:[],name:T2("Wakaf","Endowment (waqf)"),
 niat:[NV("وَقَفْتُ هَٰذَا لِلَّهِ تَعَالَى","Aku wakafkan harta ini kerana Allah Ta'ala.","I endow this property for the sake of Allah the Most High.","Lafaz wakaf (sebut harta & tujuan jika perlu)","Waqf declaration (state the property and purpose if needed)")],
 what:T2("Menahan harta yang kekal asalnya dan menyalurkan manfaatnya untuk kebaikan, seperti masjid, sekolah atau telaga.","Holding an asset whose substance remains and directing its benefit to good causes, such as a masjid, school or well."),
 why:T2("Termasuk sedekah jariah yang pahalanya berterusan selepas mati.","It is ongoing charity whose reward continues after death."),
 how:T2("Melalui Majlis Agama Islam negeri atau institusi wakaf yang sah, dengan lafaz atau dokumen wakaf.","Through the state Islamic council or a recognised waqf institution, with a declaration or waqf document."),
 when:T2("Bila-bila masa.","Any time."),
 src:"Sahih Muslim 1631; Sahih al-Bukhari 2737"},
{id:"b_wuduk",top:"bersuci",n:[],name:T2("Wuduk","Wudhu (ablution)"),
 niat:[NV("نَوَيْتُ رَفْعَ الْحَدَثِ الْأَصْغَرِ فَرْضًا لِلَّهِ تَعَالَى","Sahaja aku mengangkat hadas kecil fardu kerana Allah Ta'ala.","I intend to lift the minor impurity, as an obligation, for the sake of Allah the Most High.")],
 what:T2("Bersuci dengan air pada anggota tertentu untuk mengangkat hadas kecil. Syarat sah solat.","Washing specific limbs with water to lift minor impurity. A condition for prayer."),
 why:T2("Dosa keluar bersama titisan air wuduk. Umat Nabi ﷺ datang pada hari kiamat dengan anggota wuduk yang bercahaya.","Sins leave with the drops of wudhu water. The Prophet's ﷺ nation will come on the Day of Judgment with radiant limbs from wudhu."),
 how:T2("Rukun: niat ketika membasuh muka, basuh muka, tangan hingga siku, sapu sebahagian kepala, basuh kaki hingga buku lali, tertib.","Pillars: intention when washing the face, wash the face, arms to the elbows, wipe part of the head, wash the feet to the ankles, in order."),
 when:T2("Sebelum solat, tawaf dan memegang mushaf.","Before prayer, tawaf and touching the mushaf."),
 src:"Al-Quran 5:6; Sahih al-Bukhari 1; Sahih Muslim 244; Sahih al-Bukhari 136"},
{id:"b_mandi",top:"bersuci",n:[],name:T2("Mandi wajib","Obligatory bath (ghusl)"),
 niat:[NV("نَوَيْتُ رَفْعَ الْحَدَثِ الْأَكْبَرِ فَرْضًا لِلَّهِ تَعَالَى","Sahaja aku mengangkat hadas besar fardu kerana Allah Ta'ala.","I intend to lift the major impurity, as an obligation, for the sake of Allah the Most High.","Umum (junub, haid, nifas)","General (janabah, menses, post-natal)"),
       NV("نَوَيْتُ رَفْعَ حَدَثِ الْحَيْضِ لِلَّهِ تَعَالَى","Sahaja aku mengangkat hadas haid kerana Allah Ta'ala.","I intend to lift the impurity of menstruation, for the sake of Allah the Most High.","Selepas haid (tukar الْحَيْضِ kepada النِّفَاسِ bagi nifas)","After menstruation (use النِّفَاسِ for post-natal bleeding)")],
 what:T2("Meratakan air ke seluruh badan untuk mengangkat hadas besar selepas junub, haid atau nifas.","Washing the whole body to lift major impurity after janabah, menstruation or post-natal bleeding."),
 why:T2("Wajib sebelum solat: \"dan jika kamu junub maka bersucilah.\"","Required before prayer: \"and if you are in a state of janabah, then purify yourselves.\""),
 how:T2("Rukun: niat ketika air pertama mengenai badan, dan meratakan air ke seluruh kulit dan rambut. Sunat berwuduk dahulu seperti amalan Nabi ﷺ.","Pillars: intention as water first touches the body, and water reaching all skin and hair. Performing wudhu first is sunnah, as the Prophet ﷺ did."),
 when:T2("Selepas berlaku sebab hadas besar, sebelum solat.","After the cause of major impurity, before praying."),
 src:"Al-Quran 5:6; Sahih al-Bukhari 248"},
{id:"b_mandisunat",top:"bersuci",n:[],name:T2("Mandi sunat (Jumaat & Hari Raya)","Sunnah bath (Friday & Eid)"),
 niat:[NV("نَوَيْتُ الْغُسْلَ لِيَوْمِ الْجُمُعَةِ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku mandi sunat hari Jumaat kerana Allah Ta'ala.","I intend the sunnah bath of Friday, for the sake of Allah the Most High.","Jumaat","Friday"),
       NV("نَوَيْتُ الْغُسْلَ لِعِيدِ الْفِطْرِ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku mandi sunat Hari Raya Aidilfitri kerana Allah Ta'ala.","I intend the sunnah bath of Eid al-Fitr, for the sake of Allah the Most High.","Hari Raya (tukar الْفِطْرِ kepada الْأَضْحَى bagi Aidiladha)","Eid (use الْأَضْحَى for Eid al-Adha)")],
 what:T2("Mandi yang disunatkan untuk sebab tertentu seperti solat Jumaat, Hari Raya dan ihram.","A bath recommended for particular occasions such as Jumaat, Eid and ihram."),
 why:T2("Apabila salah seorang kamu datang ke Jumaat, hendaklah dia mandi. Ibn Umar r.a. mandi sebelum keluar solat Hari Raya.","When one of you comes to Jumaat, let him bathe. Ibn Umar used to bathe before going out for the Eid prayer."),
 how:T2("Sama seperti mandi wajib dengan niat mandi sunat.","Same as the obligatory bath, with the sunnah intention."),
 when:T2("Jumaat: dari terbit fajar, afdal sebelum ke masjid. Hari Raya: dari tengah malam.","Friday: from dawn, best just before going to the masjid. Eid: from midnight."),
 src:"Sahih al-Bukhari 877; Muwatta Malik (Kitab al-Idain)"},
{id:"b_tayammum",top:"bersuci",n:[],name:T2("Tayammum","Tayammum (dry ablution)"),
 niat:[NV("نَوَيْتُ التَّيَمُّمَ لِاسْتِبَاحَةِ فَرْضِ الصَّلَاةِ لِلَّهِ تَعَالَى","Sahaja aku bertayammum untuk mengharuskan solat fardu kerana Allah Ta'ala.","I intend tayammum to make the obligatory prayer permissible, for the sake of Allah the Most High.")],
 what:T2("Bersuci dengan debu tanah yang suci sebagai ganti wuduk atau mandi apabila tiada air atau tidak boleh menggunakan air.","Purification with clean earth dust in place of wudhu or ghusl when water is unavailable or cannot be used."),
 why:T2("Keringanan daripada Allah: \"maka bertayammumlah dengan tanah yang suci.\"","A concession from Allah: \"then seek clean earth and wipe your faces and hands.\""),
 how:T2("Niat ketika memindahkan debu ke muka, sapu muka, kemudian tepuk debu sekali lagi dan sapu kedua tangan hingga siku, tertib. Satu tayammum untuk satu solat fardu (mazhab Syafi'i).","Intention when transferring dust to the face, wipe the face, then strike the dust again and wipe both arms to the elbows, in order. One tayammum per obligatory prayer (Shafi'i school)."),
 when:T2("Selepas masuk waktu solat, apabila ada keuzuran.","After the prayer time has entered, when excused from water."),
 src:"Al-Quran 4:43; Al-Quran 5:6; Sahih al-Bukhari 338"},
{id:"h_umrah",top:"haji",n:[],name:T2("Ihram umrah","Ihram for Umrah"),
 niat:[NV("نَوَيْتُ الْعُمْرَةَ وَأَحْرَمْتُ بِهَا لِلَّهِ تَعَالَى","Sahaja aku berniat umrah dan berihram dengannya kerana Allah Ta'ala.","I intend Umrah and enter ihram for it, for the sake of Allah the Most High."),
       NV("لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ","Aku menyahut panggilan-Mu ya Allah. Tiada sekutu bagi-Mu. Sesungguhnya segala puji, nikmat dan kerajaan milik-Mu, tiada sekutu bagi-Mu.","Here I am, O Allah, here I am. You have no partner. All praise, favour and dominion are Yours; You have no partner.","Talbiyah selepas niat","Talbiyah after the intention")],
 what:T2("Memasuki ihram dengan niat umrah di miqat, lalu tawaf, saie dan bercukur atau bergunting.","Entering ihram for Umrah at the miqat, followed by tawaf, sa'i and shaving or trimming the hair."),
 why:T2("Umrah ke umrah menghapuskan dosa antara keduanya.","One Umrah to the next expiates the sins between them."),
 how:T2("Mandi sunat, pakai pakaian ihram, solat sunat ihram, niat dan bertalbiah di miqat.","Sunnah bath, wear ihram clothing, pray the ihram sunnah, then make the intention and talbiyah at the miqat."),
 when:T2("Sepanjang tahun. Niat di miqat (bagi penerbangan dari Malaysia, biasanya di atas kapal terbang atau di Qarnul Manazil).","All year. Intention at the miqat (for flights from Malaysia, usually on the plane or at Qarn al-Manazil)."),
 src:"Sahih al-Bukhari 1773; Sahih al-Bukhari 1549"},
{id:"h_haji",top:"haji",n:[],name:T2("Ihram haji","Ihram for Hajj"),
 niat:[NV("نَوَيْتُ الْحَجَّ وَأَحْرَمْتُ بِهِ لِلَّهِ تَعَالَى","Sahaja aku berniat haji dan berihram dengannya kerana Allah Ta'ala.","I intend Hajj and enter ihram for it, for the sake of Allah the Most High.")],
 what:T2("Memasuki ihram dengan niat haji, rukun Islam kelima bagi yang mampu.","Entering ihram for Hajj, the fifth pillar of Islam for those able."),
 why:T2("Haji mabrur tiada balasan baginya melainkan syurga.","An accepted Hajj has no reward but Paradise."),
 how:T2("Seperti ihram umrah, dengan niat haji. Ikut taklimat Tabung Haji untuk haji ifrad, tamattu' atau qiran.","As for Umrah ihram, with the Hajj intention. Follow Tabung Haji guidance for ifrad, tamattu' or qiran."),
 when:T2("Dalam bulan haji (Syawal, Zulkaedah, 1–10 Zulhijjah).","In the Hajj months (Shawwal, Dhul-Qa'dah, 1–10 Dhul-Hijjah)."),
 src:"Al-Quran 3:97; Sahih al-Bukhari 1773"},
{id:"l_iktikaf",top:"lain",n:[],name:T2("Iktikaf","I'tikaf (staying in the masjid)"),
 niat:[NV("نَوَيْتُ الْاِعْتِكَافَ فِي هَٰذَا الْمَسْجِدِ مَا دُمْتُ فِيهِ سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku beriktikaf di dalam masjid ini selama aku berada di dalamnya, sunat kerana Allah Ta'ala.","I intend i'tikaf in this masjid for as long as I am in it, as a sunnah, for the sake of Allah the Most High.")],
 what:T2("Berdiam di dalam masjid dengan niat beribadah.","Staying in the masjid with the intention of worship."),
 why:T2("Nabi ﷺ beriktikaf pada sepuluh malam terakhir Ramadan hingga baginda wafat.","The Prophet ﷺ observed i'tikaf in the last ten nights of Ramadan until he passed away."),
 how:T2("Masuk masjid, berniat, kemudian sibukkan diri dengan solat, zikir dan bacaan al-Quran. Dalam mazhab Syafi'i sah walaupun sebentar.","Enter the masjid, make the intention, and occupy yourself with prayer, dhikr and Quran. In the Shafi'i school it is valid even for a short while."),
 when:T2("Bila-bila masa; sangat dituntut pada 10 malam terakhir Ramadan.","Any time; especially in the last ten nights of Ramadan."),
 src:"Sahih al-Bukhari 2026"},
{id:"l_korban",top:"lain",n:[],name:T2("Korban","Qurban (udhiyah)"),
 niat:[NV("نَوَيْتُ الْأُضْحِيَّةَ الْمَسْنُونَةَ لِلَّهِ تَعَالَى","Sahaja aku melakukan korban sunat kerana Allah Ta'ala.","I intend the sunnah sacrifice, for the sake of Allah the Most High.")],
 what:T2("Menyembelih binatang ternakan (unta, lembu, kambing) pada Hari Raya Aidiladha dan hari Tasyrik.","Slaughtering livestock (camel, cattle, goat or sheep) on Eid al-Adha and the days of Tashriq."),
 why:T2("Nabi ﷺ berkorban dua ekor kibasy dengan tangan baginda sendiri.","The Prophet ﷺ sacrificed two rams with his own hand."),
 how:T2("Seekor kambing untuk seorang; lembu atau unta untuk tujuh bahagian. Niat ketika menyembelih atau ketika menentukan binatang. Disunatkan tidak memotong rambut dan kuku dari 1 Zulhijjah.","One goat per person; a cow or camel for seven shares. Intention at slaughter or when designating the animal. It is sunnah not to cut hair and nails from 1 Dhul-Hijjah."),
 when:T2("Selepas solat Hari Raya Aidiladha (10 Zulhijjah) hingga terbenam matahari 13 Zulhijjah.","After the Eid al-Adha prayer (10 Dhul-Hijjah) until sunset on 13 Dhul-Hijjah."),
 src:"Sahih al-Bukhari 5565; Sahih Muslim 1977"},
{id:"l_aqiqah",top:"lain",n:[],name:T2("Aqiqah","Aqiqah"),
 niat:[NV("نَوَيْتُ الْعَقِيقَةَ عَنْ وَلَدِي سُنَّةً لِلَّهِ تَعَالَى","Sahaja aku melakukan aqiqah untuk anakku, sunat kerana Allah Ta'ala.","I intend the aqiqah for my child, as a sunnah, for the sake of Allah the Most High.","Sebut nama anak jika mahu","Name the child if you wish")],
 what:T2("Menyembelih binatang sebagai tanda syukur atas kelahiran anak.","Slaughtering an animal in gratitude for the birth of a child."),
 why:T2("Setiap anak tergadai dengan aqiqahnya, disembelih pada hari ketujuh, dicukur dan diberi nama.","Every child is held in pledge by his aqiqah, slaughtered on the seventh day, his head shaved and he is named."),
 how:T2("Dua ekor kambing untuk anak lelaki dan seekor untuk anak perempuan, atau satu bahagian lembu. Daging disunatkan diagih dalam keadaan dimasak.","Two goats for a boy and one for a girl, or a share of a cow. It is sunnah to distribute the meat cooked."),
 when:T2("Afdal hari ketujuh kelahiran; boleh sehingga anak baligh.","Best on the seventh day; permissible until the child reaches puberty."),
 src:"Sunan Abi Dawud 2838; Jami' at-Tirmidhi 1522"}
]);

// ---- Solat jenazah (0.1.9). VERIFY by ustaz. ----
SUNAT_LIST.push({id:"jenazah",cat:"khas",top:"solat",n:[],
 name:T2("Solat Jenazah","Funeral prayer (Janazah)"),
 niat:[NV("أُصَلِّي عَلَىٰ هَٰذَا الْمَيِّتِ أَرْبَعَ تَكْبِيرَاتٍ فَرْضَ كِفَايَةٍ لِلَّهِ تَعَالَى","Sahaja aku solat ke atas jenazah (lelaki) ini empat takbir fardu kifayah kerana Allah Ta'ala.","I intend to pray over this deceased (man) with four takbirs, as a communal obligation, for the sake of Allah the Most High.","Jenazah lelaki","Male deceased"),
       NV("أُصَلِّي عَلَىٰ هَٰذِهِ الْمَيِّتَةِ أَرْبَعَ تَكْبِيرَاتٍ فَرْضَ كِفَايَةٍ لِلَّهِ تَعَالَى","Sahaja aku solat ke atas jenazah (perempuan) ini empat takbir fardu kifayah kerana Allah Ta'ala.","I intend to pray over this deceased (woman) with four takbirs, as a communal obligation, for the sake of Allah the Most High.","Jenazah perempuan","Female deceased"),
       NV("أُصَلِّي عَلَىٰ هَٰذَا الْمَيِّتِ أَرْبَعَ تَكْبِيرَاتٍ فَرْضَ كِفَايَةٍ مَأْمُومًا لِلَّهِ تَعَالَى","Sahaja aku solat ke atas jenazah ini empat takbir fardu kifayah sebagai makmum kerana Allah Ta'ala.","I intend to pray over this deceased with four takbirs, as a communal obligation, as a follower, for the sake of Allah the Most High.","Sebagai makmum (tambah مَأْمُومًا)","As a follower (add مَأْمُومًا)")],
 what:T2("Solat ke atas jenazah Muslim sebelum dikebumikan. Empat takbir, dilakukan berdiri, tanpa rukuk, sujud atau tahiyat. Hukumnya fardu kifayah.","The prayer over a deceased Muslim before burial. Four takbirs, standing throughout, with no ruku', sujud or tashahhud. It is a communal obligation (fardu kifayah)."),
 why:T2("Sesiapa menghadiri jenazah hingga disolatkan, baginya pahala satu qirat; dan sesiapa menghadirinya hingga dikebumikan, baginya dua qirat, setiap qirat seperti bukit Uhud. Jika 40 orang Muslim yang tidak syirik menyolatkannya, Allah terima syafaat mereka untuknya.","Whoever attends a funeral until the prayer, has one qirat of reward; whoever stays until burial has two, each like Mount Uhud. If forty Muslims who associate nothing with Allah pray over him, Allah accepts their intercession for him."),
 how:T2("Syarat: suci daripada hadas dan najis, tutup aurat, menghadap kiblat, jenazah sudah dimandikan dan dikafankan dan berada di hadapan. Imam berdiri setentang kepala jenazah lelaki dan setentang pinggang (punggung) jenazah perempuan. Ikut 4 takbir di bawah, kemudian salam. Angkat tangan pada setiap takbir (mazhab Syafi'i).","Conditions: free of impurity, aurat covered, facing the qiblah, the deceased washed, shrouded and placed in front. The imam stands level with the head of a man and the waist of a woman. Follow the 4 takbirs below, then give salam. Raise the hands at each takbir (Shafi'i school)."),
 when:T2("Selepas jenazah dimandikan dan dikafankan, sebelum dikebumikan. Boleh dilakukan pada bila-bila waktu, termasuk waktu dilarang, kerana ia bersebab.","After washing and shrouding, before burial. It may be prayed at any time, including the forbidden times, as it has a reason."),
 steps:[
  {t:T2("Takbir 1: niat, takbiratul ihram, kemudian baca Al-Fatihah","Takbir 1: intention, opening takbir, then recite Al-Fatihah"),ar:"اللَّهُ أَكْبَرُ • أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ • "+Q.fatihah,tr:T2("Allah Maha Besar. Kemudian Al-Fatihah (tanpa doa iftitah dan surah, menurut pendapat yang muktamad).","Allah is the Greatest. Then Al-Fatihah (no opening supplication and no surah, per the relied-upon view)."),src:"Sahih al-Bukhari 1335"},
  {t:T2("Takbir 2: selawat ke atas Nabi ﷺ (Selawat Ibrahimiyah)","Takbir 2: blessings on the Prophet ﷺ (Salawat Ibrahimiyyah)"),ar:"اللَّهُ أَكْبَرُ • اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ",tr:T2("Ya Allah, limpahkanlah selawat ke atas Muhammad dan keluarga Muhammad sebagaimana Engkau limpahkan ke atas Ibrahim dan keluarga Ibrahim; sesungguhnya Engkau Maha Terpuji lagi Maha Mulia. Ya Allah, berkatilah Muhammad dan keluarga Muhammad sebagaimana Engkau berkati Ibrahim dan keluarga Ibrahim; sesungguhnya Engkau Maha Terpuji lagi Maha Mulia.","O Allah, send blessings upon Muhammad and the family of Muhammad as You sent blessings upon Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious."),src:"Sahih al-Bukhari 3370"},
  {t:T2("Takbir 3: doa untuk jenazah","Takbir 3: supplication for the deceased"),ar:"اللَّهُ أَكْبَرُ • اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ وَعَذَابِ النَّارِ",tr:T2("Ya Allah, ampunilah dia, rahmatilah dia, sejahterakanlah dia dan maafkanlah dia. Muliakanlah tempat tinggalnya, luaskanlah tempat masuknya, mandikanlah dia dengan air, salji dan air dingin, bersihkanlah dia daripada kesalahan sebagaimana Engkau membersihkan kain putih daripada kotoran. Gantikanlah baginya rumah yang lebih baik daripada rumahnya, keluarga yang lebih baik daripada keluarganya, dan pasangan yang lebih baik daripada pasangannya. Masukkanlah dia ke dalam syurga dan lindungilah dia daripada azab kubur dan azab neraka. (Bagi perempuan, tukar ـهُ kepada ـهَا: اللَّهُمَّ اغْفِرْ لَهَا وَارْحَمْهَا ...)","O Allah, forgive him, have mercy on him, keep him safe and pardon him. Honour his resting place, widen his entrance, wash him with water, snow and hail, and cleanse him of sins as a white garment is cleansed of dirt. Give him a home better than his home, a family better than his family and a spouse better than his spouse. Admit him to Paradise and protect him from the punishment of the grave and of the Fire. (For a woman, change ـهُ to ـهَا: اللَّهُمَّ اغْفِرْ لَهَا وَارْحَمْهَا ...)"),src:"Sahih Muslim 963"},
  {t:T2("Takbir 4: doa ringkas, kemudian salam","Takbir 4: short supplication, then salam"),ar:"اللَّهُ أَكْبَرُ • اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ، وَلَا تَفْتِنَّا بَعْدَهُ، وَاغْفِرْ لَنَا وَلَهُ • السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ",tr:T2("Ya Allah, janganlah Engkau halangi kami daripada pahalanya, janganlah Engkau timpakan fitnah kepada kami selepasnya, dan ampunkanlah kami dan dia. Kemudian beri salam ke kanan (dan ke kiri). (Bagi perempuan: أَجْرَهَا، بَعْدَهَا، وَلَهَا)","O Allah, do not deprive us of his reward, do not test us after him, and forgive us and him. Then give salam to the right (and left). (For a woman: أَجْرَهَا، بَعْدَهَا، وَلَهَا)"),src:"Sunan Abi Dawud 3201; Sunan Ibn Majah 1498"}
 ],
 src:"Sahih al-Bukhari 1325; Sahih Muslim 945; Sahih Muslim 948; Sunan Abi Dawud 3194",
 note:T2("Jika jenazah kanak-kanak, pada takbir ketiga boleh dibaca: اللَّهُمَّ اجْعَلْهُ فَرَطًا وَذُخْرًا لِوَالِدَيْهِ (Ya Allah, jadikanlah dia pendahulu dan simpanan pahala bagi kedua ibu bapanya). Makmum masbuq menyempurnakan takbir yang tertinggal selepas imam memberi salam.","For a child, at the third takbir one may say: اللَّهُمَّ اجْعَلْهُ فَرَطًا وَذُخْرًا لِوَالِدَيْهِ (O Allah, make him a forerunner and a stored reward for his parents). A latecomer completes the missed takbirs after the imam's salam.")});
